def _cat_of(group, name=""):
    # Channel name wins over the list's group label: some lists file
    # 凤凰 under 其他/地方, which would hide it from 港澳台.
    if "凤凰" in name or name.startswith("TVB") or any(k in name for k in ("翡翠", "明珠", "ViuTV", "港台", "HOY", "無綫", "无线")):
        return "港澳台"
    g = re.sub(r"[^\u4e00-\u9fa5A-Za-z·]", "", group or "")
    if "央视" in g:
        return "央视"
    if "卫视" in g and "港" not in g:
        return "卫视"
    if any(k in g for k in ("凤凰", "香港", "澳门", "台湾", "港澳台")) or g == "HongKong":
        return "港澳台"
    if any(k in g for k in ("电影", "剧场", "音乐", "动画", "游戏")):
        return "影视"
    if "体育" in g or "咪咕" in g:
        return "体育"
    return "地方"


def _norm(name):
    return re.sub(r"[\s\-·_]", "", name or "").upper()


_AD_PATHS = ("/gslb/dsdqbv/",)


def _keep(name, url):
    if not url.startswith(("http://", "https://")):
        return False
    if any(p in url for p in _AD_PATHS):
        return False
    if any(k in name for k in ("支持作者", "更新时间", "公众号", "扫码")):
        return False
    if re.match(r"^\d{4}-\d{2}-\d{2}", name):
        return False
    path = url.split("?")[0].lower()
    if path.endswith((".mp4", ".mkv", ".avi", ".mp3")):
        return False
    return True


def _parse_txt(text, src, out):
    cur = None
    for ln in text.splitlines():
        ln = ln.strip()
        if not ln:
            continue
        if ln.endswith(",#genre#"):
            cur = ln[:-8]
            if "更新时间" in cur:
                cur = None
        elif "," in ln and cur:
            name, url = ln.split(",", 1)
            name, url = name.strip(), url.strip()
            if _keep(name, url):
                out.append((_cat_of(cur, name), name, url, src))


def _parse_m3u(text, src, out):
    info = None
    for ln in text.splitlines():
        ln = ln.strip()
        if ln.startswith("#EXTINF"):
            info = ln
        elif ln and not ln.startswith("#") and info:
            m = re.search(r'group-title="([^"]*)"', info)
            grp = m.group(1) if m else "Hong Kong"
            name = info.rsplit(",", 1)[-1].strip()
            if _keep(name, ln):
                out.append((_cat_of(grp if grp != "Hong Kong" else "香港", name), name, ln, src))
            info = None


def _fetch(url):
    req = urllib.request.Request(url, headers=_UA)
    with urllib.request.urlopen(req, timeout=7) as r:
        return r.read().decode("utf-8", "replace")


def _cache_path():
    try:
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), "livehub_cache.json")
    except Exception:
        return os.path.join(os.path.expanduser("~"), "livehub_cache.json")


_REFRESHING = [False]


def _build_cats(raw):
    entries = []
    kinds = {s: k for s, k, _ in _SOURCES}
    for src, text in raw.items():
        if kinds.get(src) == "m3u":
            _parse_m3u(text, src, entries)
        else:
            _parse_txt(text, src, entries)
    cats = {}
    for cat in _CAT_ORDER:
        prio = _PRIO[cat]
        chans = {}
        for c, name, url, src in entries:
            if c != cat:
                continue
            key = _norm(name)
            ch = chans.get(key)
            if ch is None:
                ch = {"name": name, "lines": [], "seen": set(), "rank": prio.index(src) if src in prio else 9}
                chans[key] = ch
            if prio.index(src) < ch["rank"]:
                ch["name"] = name
                ch["rank"] = prio.index(src)
            if url not in ch["seen"]:
                ch["seen"].add(url)
                # gslb redirector lines are ad-prone (their target rotates
                # per request, sometimes to promo streams); keep them, but
                # always behind direct lines of the same source.
                ch["lines"].append((prio.index(src) if src in prio else 9,
                                    1 if "/gslb/" in url else 0, url))
        lst = []
        for ch in chans.values():
            # Ad-prone gslb redirector lines go dead last, behind every
            # direct line regardless of source; at least one is always kept
            # as the final line even when direct lines fill the cap. The
            # node-required overseas lines for 港澳台 stay in the list so
            # they can be tapped when the node is on.
            ch["lines"].sort(key=lambda x: (x[1], x[0]))
            direct = [u for _, g, u in ch["lines"] if g == 0]
            gslb = [u for _, g, u in ch["lines"] if g == 1]
            urls = direct[:11]
            if gslb:
                urls.append(gslb[0])
            urls = urls[:12]
            if urls:
                lst.append({"name": ch["name"], "urls": urls})
        if lst:
            cats[cat] = lst
    return cats


def _refresh():
    # Live fetch (background): multi-mirror per source, then merge + save cache.
    now = time.time()
    raw = {}

    def grab(src, kind, urls):
        for u in urls:
            try:
                t = _fetch(u)
                if "#genre#" in t or "#EXTM3U" in t:
                    raw[src] = t
                    return
            except Exception:
                continue

    ths = [threading.Thread(target=grab, args=(s, k, us), daemon=True) for s, k, us in _SOURCES]
    for t in ths:
        t.start()
    for t in ths:
        t.join(16)
    if raw:
        try:
            with open(_cache_path(), "w", encoding="utf-8") as f:
                json.dump({"ts": now, "raw": raw}, f)
        except Exception:
            pass
        cats = _build_cats(raw)
        if cats:
            with _LOCK:
                _DATA["cats"] = cats
                _DATA["ts"] = now
    return _DATA["cats"]


def _refresh_bg():
    try:
        _refresh()
    finally:
        _REFRESHING[0] = False


def _load(force=False):
    # Instant first: serve disk cache (<6h) or the embedded snapshot at once,
    # refresh live lists in the background. First open/play no longer waits
    # on multi-mirror fetching (the old first-play-timeout cause).
    now = time.time()
    if _DATA["cats"] and not force and now - _DATA["ts"] < 6 * 3600:
        return _DATA["cats"]
    if force:
        return _refresh()
    with _LOCK:
        if _DATA["cats"] and time.time() - _DATA["ts"] < 6 * 3600:
            return _DATA["cats"]
        raw = {}
        try:
            with open(_cache_path(), encoding="utf-8") as f:
                saved = json.load(f)
            if time.time() - saved.get("ts", 0) < 6 * 3600 and saved.get("raw"):
                raw = saved["raw"]
        except Exception:
            pass
        if not raw:
            for k, b64 in _SNAP.items():
                try:
                    raw[k] = zlib.decompress(base64.b64decode(b64)).decode("utf-8", "replace")
                except Exception:
                    pass
        cats = _build_cats(raw)
        if cats:
            _DATA["cats"] = cats
            _DATA["ts"] = time.time()
        if not _REFRESHING[0]:
            _REFRESHING[0] = True
            threading.Thread(target=_refresh_bg, daemon=True).start()
        return _DATA["cats"]


_PROBE = {}
_AD_NAME = re.compile(r"^(mkt|byt|ad|ads|promo|gg)\d*\.m3u8$|^\d+\.m3u8$", re.I)


def _is_ad(url):
    # Some list lines are ad roulette: the redirector lands on rotating
    # promo streams (mkt.m3u8, byt.m3u8, 102.m3u8, ...) whatever channel
    # was requested. Probe once per URL (redirect target's basename is
    # the tell); probe failures keep the line.
    v = _PROBE.get(url)
    if v is not None:
        return v
    bad = False
    try:
        req = urllib.request.Request(url, headers=_UA)
        with urllib.request.urlopen(req, timeout=4) as r:
            final = r.geturl() or url
            r.read(1024)
        base = final.split("?")[0].rsplit("/", 1)[-1]
        bad = bool(_AD_NAME.match(base))
    except Exception:
        bad = False
    _PROBE[url] = bad
    return bad


_RESOLVED = {}
_LINE_BAD = {}


def _is_ad_url(url):
    base = url.split("?")[0].rsplit("/", 1)[-1]
    return bool(_AD_NAME.match(base))


def _warm_line(u):
    # Resolve the chain and prefetch the first segment: warms the CDN edge
    # for this IP and verifies the line actually flows before the player
    # touches it. A line that fails here is skipped at tap time (120s).
    try:
        ru = _resolve_chain(u)
        if _is_ad_url(ru):
            _LINE_BAD[u] = time.time()
            return
        req = urllib.request.Request(ru, headers=_UA)
        with urllib.request.urlopen(req, timeout=5) as r:
            body = r.read(32768).decode("utf-8", "replace")
            final = r.geturl() or ru
            ctype = r.headers.get_content_type()
        if not body.lstrip().startswith("#EXTM3U"):
            # A dead relay answers with an HTML error page instead of a
            # playlist; real direct streams (FLV/TS) are binary, not HTML.
            if "html" in ctype or body.lstrip().startswith("<"):
                _LINE_BAD[u] = time.time()
            return
        segs = [ln.strip() for ln in body.splitlines() if ln.strip() and not ln.startswith("#")]
        if not segs:
            _LINE_BAD[u] = time.time()
            return
        su = urllib.parse.urljoin(final, segs[0])
        req = urllib.request.Request(su, headers=_UA)
        with urllib.request.urlopen(req, timeout=5) as r:
            r.read(262144)
    except Exception:
        _LINE_BAD[u] = time.time()


def _resolve_chain(url):
    # Relay lines (jdshipin etc.) hide the real playlist behind one-entry
    # stub playlists; many players cannot follow playlist->playlist hops,
    # so resolve the chain here and hand the player the real playlist URL.
    if url in _RESOLVED:
        return _RESOLVED[url]
    cur = url
    out = url
    try:
        for _ in range(5):
            req = urllib.request.Request(cur, headers=_UA)
            with urllib.request.urlopen(req, timeout=8) as r:
                body = r.read(65536).decode("utf-8", "replace")
                final = r.geturl() or cur
            if not body.lstrip().startswith("#EXTM3U"):
                out = final
                break
            entries = [ln.strip() for ln in body.splitlines()
                       if ln.strip() and not ln.startswith("#")]
            out = final
            if len(entries) != 1:
                break
            cur = urllib.parse.urljoin(final, entries[0])
    except Exception:
        return url  # transient failure: do not cache, next tap retries
    _RESOLVED[url] = out
    return out


def _lines_for(cat, name):
    cats = _load()
    for c in cats.get(cat, []):
        if c["name"] == name:
            urls = list(c["urls"])
            if len(urls) > 1:
                verdicts = {}

                def chk(u):
                    verdicts[u] = _is_ad(u)

                ths = [threading.Thread(target=chk, args=(u,), daemon=True) for u in urls]
                for t in ths:
                    t.start()
                for t in ths:
                    t.join(5)
                good = [u for u in urls if not verdicts.get(u)]
                if good:
                    # Warm each line in parallel (resolve + first segment)
                    # so the first tap is instant and dead lines are known.
                    ths2 = [threading.Thread(target=_warm_line, args=(u,), daemon=True) for u in good]
                    for t in ths2:
                        t.start()
                    for t in ths2:
                        t.join(7)
                    return good
            return urls
    return []


class _LogoHandler(http.server.BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def do_GET(self):
        try:
            if self.path.startswith("/logo/"):
                key = urllib.parse.unquote(self.path[6:].split("?")[0])
                b64 = _LOGOS.get(key)
                if b64:
                    body = base64.b64decode(b64)
                    self.send_response(200)
                    self.send_header("Content-Type", "image/jpeg")
                    self.send_header("Content-Length", str(len(body)))
                    self.send_header("Cache-Control", "public, max-age=86400")
                    self.end_headers()
                    self.wfile.write(body)
                    return
            self.send_response(404)
            self.end_headers()
        except Exception:
            pass


def _start_server():
    if _SRV["port"]:
        return _SRV["port"]
    try:
        srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), _LogoHandler)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        _SRV["port"] = srv.server_address[1]
    except Exception as e:
        _SRV["err"] = str(e)[:60]
    return _SRV["port"]


def _logo(name):
    key = _norm(name)
    if key in _LOGOS:
        port = _start_server()
        if port:
            return "http://127.0.0.1:%d/logo/%s" % (port, urllib.parse.quote(key))
    return "https://live.fanmingming.com/tv/%s.png" % urllib.parse.quote(name)


class Spider(_BaseSpider):
    def getName(self):
        return "聚合直播"

    def getDependence(self):
        return []

    def init(self, extend=""):
        try:
            _start_server()
            t = threading.Thread(target=_load, daemon=True)
            t.start()
            t.join(6)
        except Exception:
            pass

    def homeContent(self, filter=False):
        cats = _load()
        return {"class": [{"type_id": c, "type_name": c} for c in _CAT_ORDER if c in cats],
                "filters": {}}

    def homeVideoContent(self):
        cats = _load()
        return {"list": [self._vod(c, ch) for c in ("央视",) for ch in cats.get(c, [])]}

    def _vod(self, cat, ch):
        return {"vod_id": "%s|%s" % (cat, ch["name"]), "vod_name": ch["name"],
                "vod_pic": _logo(ch["name"]), "vod_remarks": "%d 线路" % len(ch["urls"])}

    def categoryContent(self, tid, pg, filter=False, extend=None):
        cats = _load()
        lst = cats.get(tid, [])
        page = int(pg or 1)
        size = 60
        part = lst[(page - 1) * size: page * size]
        return {"page": page, "pagecount": max(1, (len(lst) + size - 1) // size),
                "limit": size, "total": len(lst),
                "list": [self._vod(tid, ch) for ch in part]}

    def detailContent(self, ids):
        if isinstance(ids, (list, tuple)):
            id_list = [str(x) for x in ids]
        else:
            id_list = [str(ids or "")]
        cats = _load()
        out = []
        for vid in id_list:
            cat, _, nm = vid.partition("|")
            ch = None
            for c in cats.get(cat, []):
                if c["name"] == nm:
                    ch = c
                    break
            if not ch:
                continue
            lines = _lines_for(cat, nm) or ch["urls"]
            eps = "#".join("线路%d$%s|%d" % (i + 1, vid, i) for i in range(len(lines)))
            out.append({"vod_id": vid, "vod_name": ch["name"], "vod_pic": _logo(ch["name"]),
                        "vod_content": "%s · 聚合直播（社区清单每日测速更新，多线路）" % ch["name"],
                        "vod_play_from": "直播", "vod_play_url": eps})
        return {"list": out}

    def playerContent(self, flag, id, vipFlags=None):
        try:
            vid, _, idx = str(id).rpartition("|")
            cat, _, nm = vid.partition("|")
            lines = _lines_for(cat, nm)
            if lines:
                start = int(idx)
                for j in range(start, len(lines)):
                    u = lines[j]
                    if time.time() - _LINE_BAD.get(u, 0) < 120:
                        continue
                    ru = _resolve_chain(u)
                    if _is_ad_url(ru):
                        _LINE_BAD[u] = time.time()
                        continue
                    return {"parse": 0, "jx": 0, "playUrl": "", "url": ru, "header": dict(_UA)}
                u = _resolve_chain(lines[start])
                return {"parse": 0, "jx": 0, "playUrl": "", "url": u, "header": dict(_UA)}
        except Exception:
            pass
        return {"parse": 0, "jx": 0, "playUrl": "", "url": "", "header": {}}

    def searchContent(self, key, quick=False, pg=1):
        cats = _load()
        res = []
        for cat in _CAT_ORDER:
            for ch in cats.get(cat, []):
                if key in ch["name"]:
                    res.append(self._vod(cat, ch))
        return {"list": res, "page": 1, "pagecount": 1, "limit": len(res), "total": len(res)}

    def localProxy(self, params):
        return None

    def action(self, action):
        return None

    def destroy(self):
        return None
